use iso532::*;
use std::sync::atomic::{AtomicUsize,Ordering};
static FAILURES: AtomicUsize=AtomicUsize::new(0);
fn emit(name:&str,pass:bool,detail:String){if !pass{FAILURES.fetch_add(1,Ordering::SeqCst);}println!("{{\"case\":\"{}\",\"pass\":{},\"detail\":{:?}}}",name,pass,detail);}
fn err(x:&[f64],fs:f64,tv:bool)->Option<Iso532Error>{if tv{loudness_zwtv(x,fs,FieldType::Free).err()}else{loudness_zwst(x,fs,FieldType::Free).err()}}
fn stream(x:&[f64])->(Vec<StreamFrame>,u32){let mut s=ZwtvStream::new(FieldType::Free);let mut all=vec![];let mut p=0;let sizes=[1,131,7,409,24,97];let mut c=0;while p<x.len(){let end=(p+sizes[c%sizes.len()]).min(x.len());let mut out=vec![StreamFrame::default();ZwtvStream::max_frames_for_chunk(end-p)];let n=s.push(&x[p..end],&mut out);all.extend_from_slice(&out[..n]);p=end;c+=1;}let mut out=[StreamFrame::default();1];let n=s.flush(&mut out);all.extend_from_slice(&out[..n]);(all,s.residual_flags().bits())}
fn compare(a:&[f64],b:&[f64])->String{if a.len()!=b.len(){return format!("length {} != {}",a.len(),b.len())}for(i,(x,y))in a.iter().zip(b).enumerate(){if x.to_bits()!=y.to_bits(){return format!("first mismatch [{}] {:016x} != {:016x}",i,x.to_bits(),y.to_bits())}}String::new()}
fn main(){
let root=std::env::args().nth(1).unwrap();
emit("error_code",Iso532Error::NonFiniteInput{idx:7}.code()==4,format!("{}",Iso532Error::NonFiniteInput{idx:7}.code()));
for tv in [false,true]{for (kind,v) in [("nan",f64::NAN),("pinf",f64::INFINITY),("ninf",f64::NEG_INFINITY)]{for idx in [0,2400,4799]{let mut x=vec![0.;4800];x[idx]=v;let e=err(&x,48000.,tv);emit(&format!("nonfinite/{tv}/{kind}/{idx}"),matches!(e,Some(Iso532Error::NonFiniteInput{idx:i}) if i==idx),format!("{e:?}"));}}
let mut x=vec![0.;4800];x[301]=f64::NAN;x[4000]=f64::INFINITY;let e=err(&x,48000.,tv);emit(&format!("first_index/{tv}"),matches!(e,Some(Iso532Error::NonFiniteInput{idx:301})),format!("{e:?}"));for(fs,len,code)in [(44100.,4800,3),(48000.,4799,2)]{x[0]=f64::NAN;let e=err(&x[..len],fs,tv);emit(&format!("precedence/{tv}/{code}"),e.as_ref().map(|e|e.code())==Some(code),format!("{e:?}"));}
for (name,v) in [("subnormal",f64::from_bits(1)),("positive_zero",0.),("negative_zero",-0.),("huge",1e300)]{let x=vec![v;4800];let e=err(&x,48000.,tv);emit(&format!("finite/{tv}/{name}"),!matches!(e,Some(Iso532Error::NonFiniteInput{..})),format!("{e:?}"));}}
for len in [4800usize,4801,4823,4824,4825,4895,4896,4897,24013,47905,47916,47927,47928,47952,47999,48000]{let x:Vec<_>=(0..len).map(|i|0.02*(i as f64*0.13).sin()).collect();let r=loudness_zwtv(&x,48000.,FieldType::Free).unwrap();let want=((len+23)/24+3)/4;let time:Vec<_>=(0..want).map(|j|(96*j)as f64/48000.).collect();let c=iso532_ffi::iso532_zwtv_out_frames(len);let d=compare(&r.time_axis,&time);emit(&format!("grid/{len}"),zwtv_out_frames(len)==want&&c==want&&r.n.len()==want&&r.n_specific.len()==240*want&&d.is_empty(),format!("frames={want}; rust={}; C={c}; spec={}; time_first={:016x}; time_last={:016x}; {d}",r.n.len(),r.n_specific.len(),r.time_axis[0].to_bits(),r.time_axis[want-1].to_bits()));}
for idx in [0,101,4799]{let mut x:Vec<_>=(0..4800).map(|i|0.01*(i as f64*0.17).sin()).collect();x[idx]=0.;let (a,_)=stream(&x);x[idx]=f64::NAN;let(b,flags)=stream(&x);let av:Vec<_>=a.iter().flat_map(|v|[v.n,v.n_phon]).collect();let bv:Vec<_>=b.iter().flat_map(|v|[v.n,v.n_phon]).collect();let d=compare(&av,&bv);let flagged:Vec<_>=b.iter().filter(|v|v.flags.contains(FrameFlags::NONFINITE_INPUT)).map(|v|v.t_frame_index).collect();emit(&format!("stream_nan/{idx}"),d.is_empty() && match idx {0=>flagged==vec![0] && flags==0,101=>flagged==vec![1] && flags==0,4799=>flagged.is_empty() && flags==2,_=>false},format!("frames={}; flagged={flagged:?}; residual={flags}; {d}",a.len()));}
let mut paths:Vec<_>=std::fs::read_dir(format!("{root}/data/annexb")).unwrap().map(|p|p.unwrap().path()).filter(|p|p.extension().and_then(|v|v.to_str())==Some("wav")).collect();paths.sort();let mut count=0;
for path in paths{let mut w=hound::WavReader::open(&path).unwrap();let sp=w.spec();if sp.sample_rate!=48000||sp.channels!=1{continue}let x:Vec<f64>=if sp.sample_format==hound::SampleFormat::Float{w.samples::<f32>().map(|s|s.unwrap()as f64*2.*2f64.sqrt()).collect()}else{let scale=2.*2f64.sqrt()/2f64.powi(sp.bits_per_sample as i32-1);w.samples::<i32>().map(|s|s.unwrap()as f64*scale).collect()};let full=loudness_zwtv(&x,48000.,FieldType::Free).unwrap();let name=path.file_name().unwrap().to_str().unwrap();for len in [4801usize,24013,47927]{if len>=x.len(){continue}let short=loudness_zwtv(&x[..len],48000.,FieldType::Free).unwrap();let f=short.n.len();let mut mismatch=compare(&short.n,&full.n[..f]);if mismatch.is_empty(){mismatch=compare(&short.time_axis,&full.time_axis[..f]);}for bark in 0..240{let d=compare(&short.n_specific[bark*f..(bark+1)*f],&full.n_specific[bark*full.n.len()..bark*full.n.len()+f]);if !d.is_empty(){mismatch=format!("Bark[{bark}] {d}");break}}emit(&format!("prefix/{name}/{len}"),mismatch.is_empty(),format!("frames={f}; words={}; first_n={:016x}; last_n={:016x}; {mismatch}",242*f,short.n[0].to_bits(),short.n[f-1].to_bits()));}
if count==0{let (s,flags)=stream(&x);let sn:Vec<_>=s.iter().map(|v|v.n).collect();let d=compare(&sn,&full.n);let index=s.iter().enumerate().all(|(j,v)|v.t_frame_index==j as u64);emit("stream_wav",d.is_empty()&&index,format!("wav={name}; frames={}; residual={flags}; chunks=[1,131,7,409,24,97]; {d}",sn.len()));}count+=1;}
let bytes=std::fs::read("tmp/acceptance-031/sig3-pressure.bin").unwrap();let x:Vec<f64>=bytes.chunks_exact(8).map(|b|f64::from_le_bytes(b.try_into().unwrap())).collect();let full=loudness_zwtv(&x,48000.,FieldType::Free).unwrap();for len in [4801usize,24013,47927]{let r=loudness_zwtv(&x[..len],48000.,FieldType::Free).unwrap();let f=r.n.len();let mut d=compare(&r.n,&full.n[..f]);if d.is_empty(){d=compare(&r.time_axis,&full.time_axis[..f]);}for bark in 0..240{let k=compare(&r.n_specific[bark*f..(bark+1)*f],&full.n_specific[bark*full.n.len()..bark*full.n.len()+f]);if !k.is_empty(){d=format!("Bark[{bark}] {k}");break}}emit(&format!("prefix/official-signal-3-resampled/{len}"),d.is_empty(),format!("frames={f}; words={}; first_n={:016x}; last_n={:016x}; {d}",242*f,r.n[0].to_bits(),r.n[f-1].to_bits()));}emit("wav_count",count>=3,format!("native 48k WAVs={count}; additional official resampled sig3=1"));
assert_eq!(FAILURES.load(Ordering::SeqCst),0,"independent contract failures");
}
